const body = $input.first().json.body || $input.first().json;

const lead_id = body.lead_id;
const name = body.name || 'Friend';
const rawPhone = (body.phone || '').replace(/\D/g, '');
const client_id = body.client_id || null;
const phone_number_id = body.phone_number_id || '';
const wa_access_token = body.wa_access_token || '';

if (!rawPhone) throw new Error('No phone number provided');
if (!client_id) throw new Error('No client_id provided — cannot determine brand');

return [{ json: { lead_id, name, phone: rawPhone, client_id, phone_number_id, wa_access_token } }];

const leadInfo = $('Extract Lead Info').first().json;
const brand = $input.first().json;

// Template name from brain_docs, fallback to common_welcome_message
const templateName = (brand.welcome_template || 'common_welcome_message').trim();

// Use brand WA credentials, fallback to what server sent
const phoneNumberId = brand.phone_number_id || leadInfo.phone_number_id;
const waToken = brand.wa_access_token || leadInfo.wa_access_token;

if (!phoneNumberId || !waToken) {
  throw new Error('Missing WhatsApp credentials for brand: ' + (brand.brand_name || 'unknown') + '. Set phone_number_id and wa_access_token in Clients.');
}

return [{
  json: {
    lead_id: leadInfo.lead_id,
    phone: leadInfo.phone,
    name: leadInfo.name,
    templateName,
    phoneNumberId,
    waToken,
    brandName: brand.brand_name || 'Unknown Brand'
  }
}];
